scripts.extract-sources.py:
"""Derive three original-Latin letter streams from pinned public witnesses."""

import hashlib
import html
import json
from pathlib import Path
import re
import unicodedata


ROOT = Path(__file__).resolve().parent

SOURCE_META = {
    "aquinas-1001.html": {
        "url": "https://www.corpusthomisticum.org/scg1001.html",
        "sha256": "fed1a3735c86ec66dfdd04819e7121bcee7fb0407787264954508984d210f105",
    },
    "aquinas-1010.html": {
        "url": "https://www.corpusthomisticum.org/scg1010.html",
        "sha256": "32bb3954538e3ca689efc79c9db6566f0dfa7b158caea96f466b79a2d082971c",
    },
    "virgil-227.txt": {
        "url": "https://gutenberg.pglaf.org/2/2/227/227.txt",
        "sha256": "c844c7d1c6fa4cf798e8bd8b13a855054820811add902e63db7edea5a4f3aa37",
    },
    "cicero-off1.html": {
        "url": "https://www.thelatinlibrary.com/cicero/off1.shtml",
        "sha256": "93b40022790bfe09c2b38778290a601e53ce4cffcaf947a3d036669fed241a04",
    },
}


def digest(data):
    return hashlib.sha256(data).hexdigest()


def read_source(name, encoding):
    raw = (ROOT / "raw" / name).read_bytes()
    assert digest(raw) == SOURCE_META[name]["sha256"], name
    return raw.decode(encoding)


def strip_tags(text):
    return html.unescape(re.sub(r"<[^>]+>", "", text))


def normalize(text):
    text = text.lower().replace("æ", "ae").replace("œ", "oe")
    return re.sub(r"[^a-z]", "", unicodedata.normalize("NFKD", text))


def aquinas():
    files = ["aquinas-1001.html", "aquinas-1010.html"]
    paragraph_pattern = r'<P TITLE="Contra Gentiles[^>]*>(.*?)</P>'
    reference_pattern = r'<SPAN CLASS="ref">.*?</SPAN>'
    prose = []
    for filename in files:
        paragraphs = re.findall(
            paragraph_pattern, read_source(filename, "latin-1"), re.I | re.S
        )
        if filename == files[0]:
            assert "Veritatem meditabitur" in paragraphs[0]
            paragraphs = paragraphs[1:]
        prose.extend(
            strip_tags(re.sub(reference_pattern, "", paragraph, flags=re.I | re.S))
            for paragraph in paragraphs
        )
    text = "\n".join(prose)
    assert len(prose) == 114 and text.startswith("Multitudinis usus")
    assert text.endswith("Et hunc dicimus Deum.")
    return text, {
        "author": "Thomas Aquinas",
        "work": "Summa contra Gentiles",
        "excerpt": "Book I, chapters 1–13, from chapter 1 paragraph 2",
        "edition": "Corpus Thomisticum, electronic Leonine text based on the Turin 1961 edition",
        "sources": files,
        "exclusions": "Navigation, title and numbering markup, chapter headings and opening Biblical epigraph. Inline authorial quotations are retained.",
    }


def virgil():
    filename = "virgil-227.txt"
    raw = read_source(filename, "ascii")
    first = re.search(r"^\s*LIBER I[ \t]*\r?$", raw, re.M)
    second = re.search(r"^\s*LIBER II[ \t]*\r?$", raw, re.M)
    assert first and second and first.end() < second.start()
    text = raw[first.end():second.start()].strip()
    assert text.startswith("ARMA virumque cano")
    assert "PROJECT GUTENBERG" not in text
    return text, {
        "author": "Virgil",
        "work": "Aeneid",
        "excerpt": "Complete Book I from Arma virumque cano",
        "edition": "Project Gutenberg Latin eBook #227, release dated 2008-04-03",
        "sources": [filename],
        "exclusions": "Book titles, other books, Gutenberg front/back matter, line numbers and nonletters.",
    }


def cicero():
    filename = "cicero-off1.html"
    raw = read_source(filename, "utf-8")
    start = "Quamquam te, Marce fili"
    end = "Sed iam ad reliqua pergamus."
    left, right = raw.index(start), raw.index(end) + len(end)
    text = strip_tags(raw[left:right])
    assert text.startswith(start) and text.endswith(end)
    return text, {
        "author": "Marcus Tullius Cicero",
        "work": "De Officiis",
        "excerpt": "Complete Book I from Quamquam te, Marce fili to Sed iam ad reliqua pergamus",
        "edition": "The Latin Library Latin electronic text",
        "sources": [filename],
        "exclusions": "Navigation, front/back matter, numerical section markers and nonletters. Letters within editorial square brackets are retained.",
    }


def main():
    manifest = {
        "normalization": "Lowercase, expand ae and oe ligatures, apply NFKD, remove every character outside a–z. Preserve j and v. Write UTF-8 with no trailing newline.",
        "reproduction": "Acquire the exact raw witnesses at the recorded URLs under raw/, verify their SHA-256 digests, and run python3 extract-sources.py.",
        "algorithm_sha256": digest(Path(__file__).read_bytes()),
        "raw_files": SOURCE_META,
        "streams": {},
    }
    for extract in (aquinas, virgil, cicero):
        text, metadata = extract()
        stream = normalize(text)
        assert len(stream) >= 12000 and re.fullmatch(r"[a-z]+", stream)
        filename = f"{extract.__name__}.txt"
        data = stream.encode("utf-8")
        (ROOT / filename).write_bytes(data)
        manifest["streams"][filename] = {
            **metadata,
            "letters": len(stream),
            "normalized_sha256": digest(data),
        }
    (ROOT / "source-manifest.json").write_text(
        json.dumps(manifest, indent=2, ensure_ascii=False) + "\n", encoding="utf-8"
    )


if __name__ == "__main__":
    main()
